def main():
    P = 10**9 + 7
    max_n = 1001
    C = [[0 for _ in range(max_n + 1)] for __ in range(max_n + 1)]
    for i in range(max_n + 1):
        for j in range(i + 1):
            if j == 0 or j == i:
                C[i][j] = 1
            else:
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % P
    T = int(input())
    for t in range(T):
        inp = list(map(int, input().strip().split(' ')))
        n = inp[0]
        a = inp[2:]
        if n + 1 == sum(a):
            n += 1
        ans = 1
        for m in a:
            ans = ans * C[n][m] % P
            n -= m
        assert n == 0
        print(ans)
if __name__ == "__main__":
    main()
