def main():
    n = int(input())
    father = [-1] + list(map(int, input().split(' ')))
    child = [[] for i in range(n)]
    for i in range(1, n):
        child[father[i]].append(i)
    depth = [0 for i in range(n)]
    anc = [[] for i in range(n)]
    max_anc_id = [i for i in range(n)]
    queue = [0]
    # BFS
    while queue:
        node = queue[0]
        queue = queue[1:]
        anc[node].append(father[node])
        for i in range(1, 20):
            if anc[node][i - 1] == -1:
                anc[node].append(-1)
            else:
                anc[node].append(anc[anc[node][i - 1]][i - 1])
        for c in child[node]:
            depth[c] = depth[node] + 1
            max_anc_id[c] = max(c, max_anc_id[node])
            queue.append(c)
    def lca(u, v):
        if depth[u] > depth[v]:
            u, v = v, u
        for i in range(20):
            if (depth[v] - depth[u]) & (1 << i):
                v = anc[v][i]
        assert depth[u] == depth[v]
        if u == v:
            return u
        for i in range(len(anc[u]) - 1, -1, -1):
            if anc[u][i] != anc[v][i]:
                u = anc[u][i]
                v = anc[v][i]
        if father[u] != father[v]:
            _u, _v = u, v
            while u != -1 and v != -1:
                u = father[u]
                v = father[v]
            u, v = _u, _v
        assert father[u] == father[v]
        return father[u]
    q = int(input())
    for _ in range(q):
        x = list(map(int, input().split(' ')))[1:]
        ans = x[0]
        for u in x[1:]:
            ans = lca(ans, u)
        print(max_anc_id[ans])
if __name__ == "__main__":
    main()
